import{_ as a,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"好书荐读：小众书也有看头儿","description":"","frontmatter":{},"headers":[{"level":2,"title":"《代码的未来》","slug":"《代码的未来》","link":"#《代码的未来》","children":[]},{"level":2,"title":"《Head First 设计模式》","slug":"《head-first-设计模式》","link":"#《head-first-设计模式》","children":[]},{"level":2,"title":"《深入理解Java虚拟机：JVM高级特性与最佳实践》","slug":"《深入理解java虚拟机-jvm高级特性与最佳实践》","link":"#《深入理解java虚拟机-jvm高级特性与最佳实践》","children":[]},{"level":2,"title":"《JavaScript 异步编程：设计快速响应的网络应用》","slug":"《javascript-异步编程-设计快速响应的网络应用》","link":"#《javascript-异步编程-设计快速响应的网络应用》","children":[]},{"level":2,"title":"《Elements of Programming Interviews》","slug":"《elements-of-programming-interviews》","link":"#《elements-of-programming-interviews》","children":[]},{"level":2,"title":"《Don’t Make Me Think》","slug":"《don-t-make-me-think》","link":"#《don-t-make-me-think》","children":[]},{"level":2,"title":"《Rework》","slug":"《rework》","link":"#《rework》","children":[]},{"level":2,"title":"《思考的乐趣：Matrix67数学笔记》","slug":"《思考的乐趣-matrix67数学笔记》","link":"#《思考的乐趣-matrix67数学笔记》","children":[]},{"level":2,"title":"《数学之美》","slug":"《数学之美》","link":"#《数学之美》","children":[]},{"level":2,"title":"《大败局 I》和《大败局 II》","slug":"《大败局-i》和《大败局-ii》","link":"#《大败局-i》和《大败局-ii》","children":[]}],"relativePath":"全栈工程师修炼指南/好书荐读：小众书也有看头儿.md","filePath":"全栈工程师修炼指南/好书荐读：小众书也有看头儿.md","lastUpdated":1779818639000}'),r={name:"全栈工程师修炼指南/好书荐读：小众书也有看头儿.md"};function s(E,e,l,o,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="好书荐读-小众书也有看头儿" tabindex="-1">好书荐读：小众书也有看头儿 <a class="header-anchor" href="#好书荐读-小众书也有看头儿" aria-label="Permalink to &quot;好书荐读：小众书也有看头儿&quot;">​</a></h1><p>你好，我是四火。</p><p>距离专栏结课已经过去几个月的时间了，从大家的反馈来看，有一些读者希望我能推荐一个书单。因此，我想在这篇文章中介绍十本书，但是我不想推荐“经典”书籍，因为所谓的经典书籍，相信你可以在很多渠道找到这方面的推荐，做这样重复的劳动其实意义不大。因此，这十本书都相对“小众”，但从我的角度来说，都是非常值得一读的。</p><p>再要说明的是，这十本书并非是围绕全栈工程师这个主题的，事实上在专栏的每一篇文章末尾，我已经给出了扩展阅读的材料。这个书单中的书，它们中一半是技术书，但也有其它方面的书籍。具体来说，五本技术，一本产品和体验设计，一本工程师文化，两本数学，还有一本经济和企业传记。当然，对于每个人来说，情况不同，选择各异，你参考就好。</p><h2 id="《代码的未来》" tabindex="-1">《代码的未来》 <a class="header-anchor" href="#《代码的未来》" aria-label="Permalink to &quot;《代码的未来》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/26993bdfe85558e5b58edf02d322fad6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/26993bdfe85558e5b58edf02d322fad6.jpg" alt=""></a></p><p>松本行弘的大作，书名有点标题党，但是通过对于Go/Dart/CoffeeScript/Lua……的介绍，对你了解各种各样的程序语言和编程范式大有裨益。他还有一本出得更早的书，我也看了，叫做《松本行弘的程序世界》，讲的内容比较杂，这两本书，再加上一本《七周七语言：理解多种编程范型》，它们于我来说，最大收获都在于视野拓展，学到了编程范型的相关知识。</p><h2 id="《head-first-设计模式》" tabindex="-1">《Head First 设计模式》 <a class="header-anchor" href="#《head-first-设计模式》" aria-label="Permalink to &quot;《Head First 设计模式》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/d0c88331b1d88ad117d21cd5682bb3ae.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/d0c88331b1d88ad117d21cd5682bb3ae.png" alt=""></a></p><p>我记得我工作没多久，就去尝试阅读GOF那本设计模式的著作了，果然，很多部分都不出意外地看不懂。因此后来真正学懂设计模式，还是从这本书开始的。如果你也有类似的情形，那么可以从这本书开始。这本书可能有点厚，可是行文极其浅显易懂，例子很有趣。至今我都认为，无论经典书籍多么具有名声，即便能把道理阐述，但是如果读者不清不楚、无法消化，这样的阅读还是弊大于利的。</p><h2 id="《深入理解java虚拟机-jvm高级特性与最佳实践》" tabindex="-1">《深入理解Java虚拟机：JVM高级特性与最佳实践》 <a class="header-anchor" href="#《深入理解java虚拟机-jvm高级特性与最佳实践》" aria-label="Permalink to &quot;《深入理解Java虚拟机：JVM高级特性与最佳实践》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/807ce1a8589c5a521d87ddf77aee93d2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/807ce1a8589c5a521d87ddf77aee93d2.jpeg" alt=""></a></p><p>关于 JVM 的书我看过两本，第一本是鼎鼎大名的《深入 Java 虚拟机》，出了好几个版本，我看的是第二版中译本，现在好像都没得卖了。另一本就是这本了，它更为实战，知识性很强。如果你是把 Java 作为你最主要的编程语言，那么 JVM 是一定要啃的，而阅读这本书就可以作为这个事情的开始。</p><h2 id="《javascript-异步编程-设计快速响应的网络应用》" tabindex="-1">《JavaScript 异步编程：设计快速响应的网络应用》 <a class="header-anchor" href="#《javascript-异步编程-设计快速响应的网络应用》" aria-label="Permalink to &quot;《JavaScript 异步编程：设计快速响应的网络应用》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/b02b8ed00f089a80ae89d51a179fb044.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/b02b8ed00f089a80ae89d51a179fb044.jpg" alt=""></a></p><p>好书不一定厚，这本书就是最好的例子。整本书只有一百页多一点，但是是对 JavaScript 异步编程很好的指导性书籍。我在看这本书的时候，JavaScript异步编程还是一个算新鲜的主题，很多原则和技巧也是第一次见到，边查资料边阅读，这本书我看了两遍。</p><p>关于 JavaScript 方面，还有一本《悟透JavaScript》，它把 JavaScript 的世界用武侠小说的口吻和类比来介绍。但是因为这本书太老，可能已经没有卖，如果感兴趣可以去 <a href="https://www.cnblogs.com/leadzen/archive/2008/02/25/1073404.html" target="_blank" rel="noreferrer">作者的博客</a> 上面看。</p><h2 id="《elements-of-programming-interviews》" tabindex="-1">《Elements of Programming Interviews》 <a class="header-anchor" href="#《elements-of-programming-interviews》" aria-label="Permalink to &quot;《Elements of Programming Interviews》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/979cce65034b4bdc9c21b2aae2dd243b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/979cce65034b4bdc9c21b2aae2dd243b.jpg" alt=""></a></p><p>这是我在这里唯一推荐的一本目前没有中文译本的英文书籍。对我来说，之前在算法学习方面，若谈及系统地学习，除了大学里面的半生不熟，就只有算法导论这本书。而这本书则是我的第二本，它覆盖了算法的方方面面，介绍了很多常见的类型。</p><p>需要提醒的是，这本书的难度比较高，打算读的话你就得准备好纸和笔，以及打一段时间战斗的心理。如果你算法导论都啃起来比较辛苦的话，就不要去尝试它了。如果不反感英文阅读，而且希望算法上一个台阶的话，这本书的帮助可以说就太大了，我非常推荐。</p><h2 id="《don-t-make-me-think》" tabindex="-1">《Don’t Make Me Think》 <a class="header-anchor" href="#《don-t-make-me-think》" aria-label="Permalink to &quot;《Don’t Make Me Think》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/97655ef4c61e9bcda96155d64cb8e029.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/97655ef4c61e9bcda96155d64cb8e029.jpg" alt=""></a></p><p>这本书我记得是工作没多久的时候，当时部门老大给我们统一买来传阅的，好像看的是中译本。它应该是我看过的第一本讲产品设计和用户体验的书了，书很薄，但是直到现在还颇有印象。篇章短小而且图文并茂，每看一小点都会有思考，这本书建议你不要看得很快，相反，要慢慢看，慢慢思考，它很适合零散时间阅读和思考。</p><h2 id="《rework》" tabindex="-1">《Rework》 <a class="header-anchor" href="#《rework》" aria-label="Permalink to &quot;《Rework》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/94e5b02bf790af6001fe2eadd8b09917.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/94e5b02bf790af6001fe2eadd8b09917.jpg" alt=""></a></p><p>距离我读这本书已经过去了八年了（当时还写了一点 <a href="https://www.raychase.net/1080" target="_blank" rel="noreferrer">读书笔记</a>），可依然被触动着。书的作者是 37signals 的创立人 Jason Fried 和 DHH（RoR 的作者）。除了这本，他们还有一本叫做《Getting Real》。</p><p>37signals 是一家颇为特别的公司，小，但是非常酷，有一些想法令人叫绝。书里提到当时整个公司只有 35 名员工，遍布世界各地。我当然喜欢做大事的大公司，但是更喜欢那些做大事的小公司。精英文化、创业文化，激动人心、宽松自由，可以做有趣的工作，为了梦想而生活。</p><p>整本书都在做价值观的宣扬。我想这大概是我读过的唯一一本这种类型的书，在这里我随便摘录几条语句带你感受一下：</p><ul><li>短期内大批招人的后果就同陷入“全是陌生人的鸡尾酒会”一样。你身边充斥着新面孔，每个人都彬彬有礼，每个人都努力避免矛盾或冲突，没有人说：“这点子真烂”。人们一团和气，互不攻击。</li><li>要避免招到监工型的人物，这些人喜欢对别人谆谆教导。</li><li>ASAP（As Soon As Possible，越快越好）具有通货膨胀性。它将那些不带 ASAP 标签的事情贬值。</li></ul><h2 id="《思考的乐趣-matrix67数学笔记》" tabindex="-1">《思考的乐趣：Matrix67数学笔记》 <a class="header-anchor" href="#《思考的乐趣-matrix67数学笔记》" aria-label="Permalink to &quot;《思考的乐趣：Matrix67数学笔记》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/1a94d5296fa6d438aa1b684e23bf7545.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/1a94d5296fa6d438aa1b684e23bf7545.jpg" alt=""></a></p><p>对于软件工程师来说，除了老本行，还要学一点数学。有一些数学原理和技巧更是在软件这一行广泛应用，比如概率和统计。数学方面科普书有很多，我也看过不少，但是能够写得生动有趣，阅读过程中还能学到很多原理技巧的，可谓少之又少。</p><p>这是我非常喜欢的一本介绍数学的书，其中都是很有乐趣的问题，不需要多么深奥的数学功底，但有许多问题的证明简直让人拍案叫绝。有一些过往的疑惑得到了解答和串联。国庆期间看完了这本书，再次感慨，数学真的太有意思了。如果你意犹未尽，作者还写过一本类似的《浴缸里的惊叹：256道让你恍然大悟的趣题》，不过我认为没有这本精彩。另，作者的网站在 <a href="http://www.matrix67.com/" target="_blank" rel="noreferrer">这里</a>。</p><p>如果你特别喜欢这样主题的书，那么还有一本，叫做《从一到无穷大：科学中的事实和臆测》，也推荐给你。</p><h2 id="《数学之美》" tabindex="-1">《数学之美》 <a class="header-anchor" href="#《数学之美》" aria-label="Permalink to &quot;《数学之美》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/689b63f9ddd1ae92d0099e6f20de125f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/689b63f9ddd1ae92d0099e6f20de125f.jpg" alt=""></a></p><p>吴军老师的书适合我这种数学基础不是很优秀的程序员。我记得在我当时阅读这本书的时候，我还对于数学在软件行业的实际应用知之甚少，它可以说是让我大开眼界。这本书最厉害的地方是，能够将复杂的数学原理用浅显易懂的话大致地介绍清楚。</p><h2 id="《大败局-i》和《大败局-ii》" tabindex="-1">《大败局 I》和《大败局 II》 <a class="header-anchor" href="#《大败局-i》和《大败局-ii》" aria-label="Permalink to &quot;《大败局 I》和《大败局 II》&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/c2720fff8a3d8d58514125b696d83ab4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E6%A0%88%E5%B7%A5%E7%A8%8B%E5%B8%88%E4%BF%AE%E7%82%BC%E6%8C%87%E5%8D%97/images/215718/c2720fff8a3d8d58514125b696d83ab4.jpg" alt=""></a></p><p>要想了解中国的经济和企业，吴晓波这本书写的故事很精彩。有句话说得好，成功的人总是不一样的，但是失败的人你总能总结出一些共性。这些案例中的企业，对于八零后的我来说，有一些简直是如雷贯耳。它们辉煌的时候是怎样的？它们又是怎样一步步走向衰落的？相比于各种成功学和心灵鸡汤，看这些失败的企业案例很有触动。</p><p>同样是经济和企业传记方面，如果你只是针对 IT 行业感兴趣，那么你可以读一下《浪潮之巅》；如果你只对中国的 IT 行业感兴趣，那么吴晓波还写过一本《腾讯传》推荐给你——它里面最精彩的部分，是了解腾讯怎样在这个互联网野蛮生长的国度，和各种各样的对手，用怎样的手腕和技巧，斗争、革命，并生存下来，发展壮大。要读懂中国互联网，不读腾讯是不行的。</p><p>好，我是四火。书单推荐就到这里，希望对你有用。</p>',43)])])}const b=a(r,[["render",s]]);export{g as __pageData,b as default};
